#include <bits/stdc++.h>
using namespace std;
int main(){
    int c;
    cin >> c;
    while(c--){
        long long n; cin >> n;
        long long best = LLONG_MAX;
        for (long long a=1; a*a*a<=n; a++){
            if (n % a) continue;
            long long m = n/a;
            for (long long b=a; b*b<=m; b++){
                if (m % b) continue;
                long long cc = m/b;
                if (cc < b) continue;
                long long area = 2*(a*b+b*cc+a*cc);
                best = min(best, area);
            }
        }
        cout << best << "\n";
    }
}

