#include <bits/stdc++.h>
using namespace std;
int main(){
    int c;
    cin >> c;
    while(c--){
        long long n; cin >> n;
        long long best = -1;
        for (long long a=1; a<=n && best==-1; a++){
            if (n % a) continue;
            long long m = n/a;
            for (long long b=1; b<=m && best==-1; b++){
                if (m % b) continue;
                long long cc = m/b;
                best = 2*(a*b+b*cc+a*cc);
            }
        }
        cout << best << "\n";
    }
}
